sys_ui_action.client_script_v2:
function onClick(g_form) {
    var recordID = g_form.getUniqueValue();
    var ga = new GlideAjax('x_vuram_financia_0.FinCrimeSummarize');
    ga.addParam('sysparm_name', 'summarizeQuote');
    ga.addParam('sysparm_recordSysId', recordID);
    ga.getXMLAnswer(callback);

    function callback(response) {
        var answer = response;
        //alert(answer);
        var fields = [{
                type: 'textarea',
                name: 'summary',
                label: 'Summary',
                value: answer
            }
        ];

        g_modal.showFields({
            title: "Summary",
            fields: fields,
            size: 'lg'
        });

    }
}

sys_ui_action.script:
var inputsPayload = {};
inputsPayload['fcc_kyc_case'] = {
  tableName: 'x_vuram_financia_0_fcc_kyc_cases',
  sysId: current.getValue('sys_id'),
  queryString: ''
};

var capabilityId = '894c863e3b3fae50f13f5fea26e45a1b'; 
var request = {
	executionRequests: [{
		payload: inputsPayload,
		capabilityId: capabilityId,
		meta: {
			skillConfigId: '614cca7e3b3fae50f13f5fea26e45aaf'
		}
	}], 
	mode: 'sync' 
};

try {
	var response = sn_one_extend.OneExtendUtil.execute(request) || {}; 
	var skillResponse = ((response["capabilities"] || {})[capabilityId] || {})["response"]; 
} catch(e) {
	gs.error(e);
	gs.addErrorMessage('Something went wrong while executing skill.');
}
action.setRedirectURL(current);
